#![allow(unused_imports)]
use vstd::prelude::*;

verus! {
    /// Given a non‐empty vector of 32‐bit signed integers, returns its maximum element.
    /// 
    /// We scan from left to right, maintaining:
    ///  1. `current_max` is at least as large as every element seen so far, and
    ///  2. `current_max` is equal to some element in the prefix processed so far.
    /// The loop index `i` goes from 1 to `nums.len()`, strictly decreasing the
    /// number of unprocessed elements each iteration.
    pub fn find_max(nums: Vec<i32>) -> (ret: i32)
        requires
            nums.len() > 0,
        ensures
            // The result is at least as large as every element in the array
            forall |j: usize| j < nums.len() ==> ret >= nums[j],
        ensures
            // The result equals some element of the array
            exists |j: usize| j < nums.len() && ret == nums[j],
    {
        // Initialize: we've "processed" index 0
        let mut i: usize = 1;
        let mut current_max: i32 = nums[0];

        // Loop until we've processed all elements
        while i < nums.len()
            invariant
                // i stays between 1 and nums.len()
                0 < i && i <= nums.len(),
            invariant
                // current_max ≥ every element in nums[0..i]
                forall |k: usize| k < i ==> current_max >= nums[k],
            invariant
                // current_max = nums[k] for some k < i
                exists |k: usize| k < i && current_max == nums[k],
            decreases
                // each iteration increments i, so the unprocessed count decreases
                nums.len() - i
        {
            // Incorporate nums[i] into the prefix
            if nums[i] > current_max {
                current_max = nums[i];
            }
            i += 1;
        }

        // At this point i == nums.len(), and the invariants give the post‐conditions
        current_max
    }
}